const body = $json.body || $json;
const text = String(body.documentText || body.text || body.content || '').trim();
if (!text) throw new Error('Belge metni bulunamadi. documentText alanini gonderin.');
if (text.length < 20) throw new Error('Belge metni analiz icin cok kisa.');
const country = String(body.country || 'Türkiye');
const language = String(body.language || 'tr');
const userGoal = String(body.userGoal || 'Belgeyi incele, haklari ve itiraz yollarini belirle; gerekiyorsa dilekce hazirla.');
return [{json:{documentText:text.slice(0,120000),country,language,userGoal,receivedAt:new Date().toISOString()}}];

const d=$json;
const system=`Sen Kâtip adlı belge analiz motorusun. Kullanıcının resmi veya hukuki belgesini sade ve dikkatli biçimde analiz et. Hukuki temsilci gibi davranma; kesin sonuç garantisi verme. Belgeden çıkarılamayan bilgileri uydurma. Tarih, süre, kurum ve parasal tutarlarda belgedeki metne sadık kal. Süre belirsizse bunu açıkça belirt. Yanıt sadece geçerli JSON olsun.`;
const prompt=`Ülke: ${d.country}
Kullanıcının amacı: ${d.userGoal}

BELGE:
${d.documentText}

Aşağıdaki JSON şemasına göre yanıt ver:
{
  "documentType": "belge türü",
  "summary": "kısa sade özet",
  "issuer": "belgeyi düzenleyen kurum/kişi veya bilinmiyor",
  "importantDates": [{"date":"...","meaning":"..."}],
  "amounts": [{"amount":"...","meaning":"..."}],
  "rights": ["kullanıcının olası hakları"],
  "obligations": ["yükümlülükler"],
  "deadlines": [{"deadline":"...","action":"...","confidence":"high|medium|low"}],
  "objectionOptions": [{"route":"...","where":"...","how":"..."}],
  "risks": ["kaçırılmaması gereken riskler"],
  "nextSteps": ["öncelik sırasıyla yapılacaklar"],
  "petitionNeeded": true,
  "petition": "Gerekiyorsa doğrudan kullanılabilecek taslak dilekçe; gerekmiyorsa boş string",
  "missingInformation": ["analizi güçlendirecek eksik bilgiler"],
  "disclaimer": "Bu çıktı bilgilendirme amaçlıdır; kritik süre ve işlemler için ilgili kurum veya uzman doğrulaması önerilir."
}`;
return [{json:{...d,openaiRequest:{model:'gpt-5-mini',store:false,input:[{role:'system',content:[{type:'input_text',text:system}]},{role:'user',content:[{type:'input_text',text:prompt}]}]}}}];

const r=$json;
let text='';
if (typeof r.output_text==='string') text=r.output_text;
if (!text && Array.isArray(r.output)) { for (const o of r.output) { if (Array.isArray(o.content)) { for (const c of o.content) { if (typeof c.text==='string') text += c.text; } } } }
if (!text) throw new Error('AI yaniti bos geldi.');
text=text.trim().replace(/^```json\s*/i,'').replace(/```$/,'').trim();
let analysis;
try { analysis=JSON.parse(text); } catch(e) { analysis={summary:text,parseWarning:'AI yaniti JSON olarak ayrıştırılamadı.'}; }
return [{json:{ok:true,product:'Kâtip',version:'3',analysis}}];
